namespace Maintenance.Api.Models;

/// <summary>
/// A maintenance intervention (repair or work order) managed by the Maintenance service.
/// Related requirements: MNT-01, MNT-02, MNT-03, MNT-07.
/// </summary>
public class Intervention
{
    /// <summary>Unique identifier, generated by the service on creation (MNT-01).</summary>
    public int Id { get; set; }

    /// <summary>Description of the problem. Required (MNT-01).</summary>
    public string Description { get; set; } = "";

    /// <summary>Address or location of the intervention. Required (MNT-01).</summary>
    public string Location { get; set; } = "";

    /// <summary>Type of issue, e.g. Road, Water, Electrical. Required (MNT-01).</summary>
    public string IssueType { get; set; } = "";

    /// <summary>Priority: Low, Medium, High or Critical (MNT-03).</summary>
    public string Priority { get; set; } = "Medium";

    /// <summary>Operational status. New interventions start as "To Do" (MNT-01, MNT-07).</summary>
    public string Status { get; set; } = "To Do";

    /// <summary>Date and time (UTC) the intervention was created (MNT-01).</summary>
    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
}
